public class JumpGame {
    public boolean canJump(int[] nums) {
        int farthest = 0;
        for (int i = 0; i < nums.length; i++) {
            if (i > farthest) return false;      // i 不可达，后面更不可能
            farthest = Math.max(farthest, i + nums[i]); // 扩展覆盖范围
            if (farthest >= nums.length - 1) return true; // 已覆盖末尾
        }
        return true; // 数组长度为 1 时走这里
    }
}

public class JumpGameII {
    public int jump(int[] nums) {
        int jumps = 0;
        int currentEnd = 0;   // 当前这一跳能到的最远位置
        int farthest = 0;     // 下一跳能到的最远位置

        for (int i = 0; i < nums.length - 1; i++) {
            farthest = Math.max(farthest, i + nums[i]);
            if (i == currentEnd) {   // 到达当前跳的边界
                jumps++;
                currentEnd = farthest; // 刷新为下一跳的边界
                if (currentEnd >= nums.length - 1) break;
            }
        }
        return jumps;
    }
}
